addEventListener('scroll',()=>{const heroP=Math.min(1,scrollY/(innerHeight*.58)),next=Math.min(heroFrames.length-1,Math.round(heroP*(heroFrames.length-1)));document.documentElement.style.setProperty('--hero-progress',heroP);document.documentElement.style.setProperty('--hero-film-scale',String(1+heroP*.22));document.documentElement.style.setProperty('--hero-shift-x',`${heroP*6}vw`);document.documentElement.style.setProperty('--hero-shift-y',`${-heroP*2.5}vh`);if(next!==heroFrame){heroFrame=next;$('#heroSequence').src=heroFrames[next]}const inside=$('#inside'),parts=$('#parts');if(inside&&parts){const r=inside.getBoundingClientRect(),range=inside.offsetHeight-innerHeight,p=Math.max(0,Math.min(1,-r.top/range)),explode=Math.max(0,Math.min(1,(p-.18)/.82)),step=p<.22?0:Math.min(4,Math.floor((p-.22)/.78*4)+1),labels=['MONO ASSEMBLED','ZOOM CORE','OPTICAL ARRAY','XR SENSOR','FRONT HOUSING'];parts.style.setProperty('--inside-p',p);parts.style.setProperty('--explode',explode);parts.style.setProperty('--rear-x',`${-14-7*explode}vw`);parts.style.setProperty('--core-x',`${-4-3*explode}vw`);parts.style.setProperty('--lenses-x',`${2+4*explode}vw`);parts.style.setProperty('--sensor-x',`${7+10*explode}vw`);parts.style.setProperty('--front-x',`${13+15*explode}vw`);$('#insideStep').textContent=String(step+1).padStart(2,'0');$('#insideLabel').textContent=labels[step]}const story=$('#horizontalStory');if(story){const r=story.getBoundingClientRect(),range=story.offsetHeight-innerHeight,p=Math.max(0,Math.min(1,-r.top/range)),track=$('#horizontalTrack'),cards=$$('.cinema-card',track),max=Math.max(0,track.scrollWidth-innerWidth*.56),active=Math.min(cards.length-1,Math.round(p*(cards.length-1)));track.style.transform=`translateX(${-p*max}px)`;cards.forEach((c,i)=>c.classList.toggle('active',i===active));$('#cinemaCurrent').textContent=String(active+1).padStart(2,'0');$('#horizontalProgress').style.width=`${p*100}%`;drawStoryFrame(Math.max(0,Math.min(1,(p-.18)/.28)))}},{passive:true});
const stage=$('#xrStage'), world=$('#xrWorld'), levels=[{z:'1×',l:'REALITY',s:1},{z:'3×',l:'RECOGNIZE',s:1.28},{z:'5×',l:'IDENTIFY',s:1.62},{z:'10×',l:'DISCOVER',s:2.12}]; let level=0,dragY=null,dragX=null,panX=0,panY=0;
function setLevel(n){level=Math.max(0,Math.min(3,n));world.className=`xr-world level-${level}`;world.style.setProperty('--world-scale',levels[level].s);$('#zoomValue').textContent=levels[level].z;$('#zoomLabel').textContent=levels[level].l;$('#physicalRing').style.setProperty('--ring-rotation',`${level*38}deg`);$$('.zoom-scale button').forEach((b,i)=>b.classList.toggle('active',i===level))}
