world.addEventListener('wheel',e=>{e.preventDefault();setLevel(level+(e.deltaY>0?1:-1))},{passive:false});world.addEventListener('pointerdown',e=>{dragY=e.clientY;dragX=e.clientX;world.setPointerCapture(e.pointerId)});world.addEventListener('pointermove',e=>{if(dragY===null)return;const dx=e.clientX-dragX,dy=e.clientY-dragY;if(level>0)setPan(panX+dx/22,panY+dy/28);if(Math.abs(dy)>70&&Math.abs(dy)>Math.abs(dx)*1.4){setLevel(level+(dy<0?1:-1))}dragX=e.clientX;dragY=e.clientY});world.addEventListener('pointerup',()=>{dragY=null;dragX=null});
